 36	export function layout({ title, active, body }) {
 37	  const nav = NAV.map((item) => {
 38	    const current = item.href === active ? ' aria-current="page"' : '';
 39	    return `<a href="${item.href}"${current}>${escapeHtml(item.label)}</a>`;
 40	  }).join('');
 41	  return `<!doctype html>
 42	<html lang="en">
 43	<head>
 44	<meta charset="utf-8">
